package config

import (
	"fmt"
	"os"
	"path/filepath"
	"time"
)

// GenerateDefaultFile renders a single-file, commented config.lua that
// reflects Defaults() exactly. It is not hand-copied from Defaults() and
// then left to drift: TestGenerateDefaultFileMatchesDefaults loads the
// generated bytes back through the real loader and compares the result to
// Defaults(), so the two can't silently diverge.
func GenerateDefaultFile() []byte {
	d := Defaults()
	return []byte(fmt.Sprintf(`-- Gomodoro configuration.
-- https://github.com/gustavommcv/gomodoro

-- This file can be split into modules with require(), resolved relative
-- to this file's own directory, e.g.:
--
--   local timer = require("settings.timer")
--
-- See the README for a full modular example.

return {
	version = 1,

	timer = {
		work = %q,
		short_break = %q,
		long_break = %q,
	},

	alerts = {
		notify = %v,
		sound = %v,
	},

	style = {
		-- Reserved for a future theming feature. "default" is the only
		-- value that currently means anything, and it has no visual
		-- effect yet.
		theme = %q,
	},
}
`,
		formatMinutes(d.Timer.Work),
		formatMinutes(d.Timer.ShortBreak),
		formatMinutes(d.Timer.LongBreak),
		d.Alerts.Notify,
		d.Alerts.Sound,
		d.Style.Theme,
	))
}

func formatMinutes(d time.Duration) string {
	return fmt.Sprintf("%dm", int(d.Minutes()))
}

// WriteDefaultFile writes GenerateDefaultFile()'s content to path,
// creating its parent directory if needed. The write is atomic (a
// temporary file in the same directory, written and closed, then renamed
// into place) so a crash or failure never leaves a partially-written
// config.lua; the temporary file is removed on any failure path.
func WriteDefaultFile(path string) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return fmt.Errorf("create config directory: %w", err)
	}

	tmp, err := os.CreateTemp(dir, ".gomodoro-config-*.tmp")
	if err != nil {
		return fmt.Errorf("create temporary file: %w", err)
	}
	tmpPath := tmp.Name()

	if _, err := tmp.Write(GenerateDefaultFile()); err != nil {
		tmp.Close()
		os.Remove(tmpPath)
		return fmt.Errorf("write temporary file: %w", err)
	}
	if err := tmp.Close(); err != nil {
		os.Remove(tmpPath)
		return fmt.Errorf("close temporary file: %w", err)
	}
	if err := os.Chmod(tmpPath, 0o644); err != nil {
		os.Remove(tmpPath)
		return fmt.Errorf("set config file permissions: %w", err)
	}
	if err := os.Rename(tmpPath, path); err != nil {
		os.Remove(tmpPath)
		return fmt.Errorf("finalize config file: %w", err)
	}
	return nil
}
